WITH monthly AS (SELECT member_id, CAST(date_trunc('month', ordered_at) AS DATE) AS month_start, COUNT(*) AS order_count FROM {{ ref('orders_enriched') }} WHERE status = 'paid' AND paid_cents - refund_cents > 0 GROUP BY member_id, CAST(date_trunc('month', ordered_at) AS DATE)) SELECT member_id, month_start, order_count, member_id || '|' || CAST(month_start AS VARCHAR) AS member_month_key FROM monthly